import json, re, sys
SRC='/home/claude/avitime-site/public/index.html'
DST='/home/claude/avitime-site/public/en/index.html'
s=open(SRC).read()
missing=[]
def R(a,b,n=None):
    global s
    c=s.count(a)
    if c==0: missing.append(a[:90]); return
    if n is not None and c!=n: missing.append(f'COUNT {c}!={n}: '+a[:80]); return
    s=s.replace(a,b)

