R('"name": "Avitime en 40 secondes", "description": "Présentation du fonctionnement d’Avitime : sélection des testeurs, commande à 0 €, livraison, test et publication de l’avis."','"name": "Avitime in 40 seconds", "description": "How Avitime works: tester selection, €0 order, delivery, testing and review publication (French voice-over)."')
FAQ=[
("Are fake reviews illegal?","Yes. In France, publishing or commissioning fake reviews, posing as a consumer or presenting reviews as verified without verifying them are misleading commercial practices. According to the DGCCRF (the French consumer protection authority), they are punishable by two years’ imprisonment and a €300,000 fine, which can be raised to 10% of average annual turnover. Fake reviews are also banned across the EU (Omnibus Directive) and in the UK (DMCC Act 2024)."),
("How many reviews will a store get?","Avitime guarantees no volume of reviews. Every free product is really ordered and delivered to a selected tester, who commits to publishing a review within the agreed time. The dashboard shows exactly how many missions are completed."),
("Can a store choose its testers?","No. It sets the campaign criteria (country, category, exclusions), but the final selection is made by Avitime. That is what keeps reviews independent."),
("What happens if a review is negative?","It is published, just like a positive one, if it is genuine and meets the moderation rules. The tester keeps the product and is never penalised for their rating."),
("Who ships the products?","The store, with its usual carriers. Avitime neither stores nor ships products."),
("Which platforms are supported?","PrestaShop and WooCommerce, with a dedicated module and extension you download from your merchant account. Shopify: the Avitime app is being reviewed for the Shopify App Store. More platforms will follow."),
("I am a tester: how much does it cost?","Nothing. Sign-up is free, the product and shipping are free, and there is no subscription."),
("Which products can be tested?","The pilot starts with non-regulated accessories. Sensitive categories (health, supplements, nicotine, alcohol, products for minors…) follow a strict eligibility policy."),
]
m=re.search(r'<script type="application/ld\+json">\{"@context": "https://schema.org", "@type": "FAQPage".*?</script>',s)
faq_ld={"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in FAQ]}
s=s[:m.start()]+'<script type="application/ld+json">'+json.dumps(faq_ld,ensure_ascii=False)+'</script>'+s[m.end():]
